module dragon (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [7:0] arr_0,\n    input [7:0] arr_1,\n    input [7:0] arr_2,\n    input [7:0] arr_3,\n    input [7:0] arr_4,\n    input [7:0] arr_5,\n    input [7:0] arr_6,\n    input [7:0] arr_7,\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE_STATE = 2'd2;\n    reg [1:0] state;\n    reg [1:0] next_state;\n\n    // Processing registers\n    reg [3:0] i;\n    reg [7:0] dp0;\n    reg [7:0] dp1;\n    reg [7:0] dp2;\n    reg [7:0] dp3;\n    reg [7:0] temp_result;\n\n    // Array element selection function\n    function [7:0] read_array;\n        input [3:0] idx;\n        begin\n            case (idx)\n                4'd0: read_array = arr_0;\n                4'd1: read_array = arr_1;\n                4'd2: read_array = arr_2;\n                4'd3: read_array = arr_3;\n                4'd4: read_array = arr_4;\n                4'd5: read_array = arr_5;\n                4'd6: read_array = arr_6;\n                4'd7: read_array = arr_7;\n                default: read_array = 8'd0;\n            endcase\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            i <= 4'd0;\n            dp0 <= 8'd0;\n            dp1 <= 8'd0;\n            dp2 <= 8'd0;\n            dp3 <= 8'd0;\n            temp_result <= 8'd0;\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 8'd0;\n                    temp_result <= 8'd0;\n                    if (start) begin\n                        i <= 4'd0;\n                        dp0 <= 8'd0;\n                        dp1 <= 8'd0;\n                        dp2 <= 8'd0;\n                        dp3 <= 8'd0;\n                        next_state <= COMPUTE;\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (i < n) begin\n                        if (read_array(i) == 8'd1) begin\n                            dp0 <= dp0 + 8'd1;\n                            dp2 <= (dp1 > dp2) ? (dp1 + 8'd1) : (dp2 + 8'd1);\n                        end else begin\n                            dp1 <= (dp0 > dp1) ? (dp0 + 8'd1) : (dp1 + 8'd1);\n                            dp3 <= (dp2 > dp3) ? (dp2 + 8'd1) : (dp3 + 8'd1);\n                        end\n                        i <= i + 4'd1;\n                        next_state <= COMPUTE;\n                    end else begin\n                        // Compute final result\n                        temp_result <= dp3;\n                        if (dp0 > temp_result) temp_result <= dp0;\n                        if (dp1 > temp_result) temp_result <= dp1;\n                        if (dp2 > temp_result) temp_result <= dp2;\n                        next_state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    result <= temp_result;\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n                \n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule